<?php
/**
 * MAARS Core — answer the old site's addresses.
 *
 * ks0man.org was the old site's other name. The webmaster's pages linked
 * www.ks0man.org/Salina_Hamfest_schedule_2015.pdf, www.ks0man.org/set.rtf and
 * thirty-odd more, and ks0man.org is THIS site now: an old link or bookmark to
 * one of those addresses arrives here and, without this file, gets a 404.
 *
 * inc/legacy-map.php, generated by tools/build_redirects.py from the
 * repository, says what each old file name is now: an archive record (by the
 * source file it was made from), an attachment (by the name it shipped under),
 * a page, the gaps page, or gone. This file resolves that against the database
 * of whatever install it runs on, so the map carries no upload paths, and
 * redirects. Only a request that would otherwise be a 404, for an address
 * named in the map, is touched, so nothing WordPress answers can be shadowed.
 * The old site was one flat directory; the few deeper paths in the map are
 * links that lost their site's name ("files/file/Clubs/Tips and Tonics ...",
 * the ARRL's path with the ARRL left off), and they go to the document at the
 * address the webmaster's own copy of the page gives.
 *
 * Pointing ks0man.com at this site would make every one of its old addresses
 * work the same way, with no rewrite rules on the old host.
 *
 * @package MAARS
 */

defined( 'ABSPATH' ) || exit;

/**
 * The generated map: old name (lower case) => array( kind, key ).
 *
 * @return array<string,array{0:string,1:string}>
 */
function maars_legacy_map(): array {
	static $map = null;
	if ( null === $map ) {
		$file = __DIR__ . '/legacy-map.php';
		$map  = file_exists( $file ) ? (array) require $file : array();
	}
	return $map;
}

/**
 * The record made from a source file, by the file's name.
 *
 * @param string $source Source file name, e.g. "newsletter_03-01.html".
 * @return string Permalink, or '' when there is no such record.
 */
function maars_legacy_record_url( string $source ): string {
	$found = get_posts(
		array(
			'post_type'      => 'maars_publication',
			'post_status'    => 'publish',
			'posts_per_page' => 1,
			'fields'         => 'ids',
			'no_found_rows'  => true,
			'meta_query'     => array(
				array(
					'key'     => '_maars_source_file',
					'value'   => array( 'mirror/ks0man.com/' . $source, 'webmaster-folder/' . $source ),
					'compare' => 'IN',
				),
			),
		)
	);
	return $found ? (string) get_permalink( (int) $found[0] ) : '';
}

/**
 * An attachment by the name it shipped under, at the size it was uploaded.
 *
 * Tried in order: _maars_media_file (written by tools/import_media.php); the
 * stored file name, including WordPress's -scaled copy of a large image; and
 * the slug, which is how a REST upload is named.
 *
 * @param string $file Shipped name, e.g. "francis-2007-1-original.jpg".
 * @return string URL, or '' when there is no such attachment.
 */
function maars_legacy_file_url( string $file ): string {
	$stem = pathinfo( $file, PATHINFO_FILENAME );
	$ext  = pathinfo( $file, PATHINFO_EXTENSION );

	$queries = array(
		array(
			'meta_key'   => '_maars_media_file',
			'meta_value' => $file,
		),
		array(
			'meta_query' => array(
				'relation' => 'OR',
				array(
					'key'     => '_wp_attached_file',
					'value'   => '/' . $file,
					'compare' => 'LIKE',
				),
				array(
					'key'     => '_wp_attached_file',
					'value'   => '/' . $stem . '-scaled.' . $ext,
					'compare' => 'LIKE',
				),
			),
		),
		array( 'name' => sanitize_title( $stem ) ),
	);

	foreach ( $queries as $query ) {
		$found = get_posts(
			array_merge(
				array(
					'post_type'      => 'attachment',
					'post_status'    => 'inherit',
					'posts_per_page' => 1,
					'fields'         => 'ids',
					'no_found_rows'  => true,
				),
				$query
			)
		);
		if ( ! $found ) {
			continue;
		}
		$id  = (int) $found[0];
		$url = function_exists( 'wp_get_original_image_url' ) ? wp_get_original_image_url( $id ) : false;
		if ( ! is_string( $url ) || '' === $url ) {
			$url = wp_get_attachment_url( $id );
		}
		if ( is_string( $url ) && '' !== $url ) {
			return $url;
		}
	}
	return '';
}

/**
 * Where an old file name goes now.
 *
 * @param string $name Old file name, any case.
 * @return array{0:int,1:string,2:bool} HTTP status, URL, and whether the URL is
 *                                     another site's; status 0 when the name is unknown.
 */
function maars_legacy_target( string $name ): array {
	$map = maars_legacy_map();
	$key = strtolower( $name );
	if ( ! isset( $map[ $key ] ) ) {
		return array( 0, '', false );
	}

	list( $kind, $ref ) = $map[ $key ];
	switch ( $kind ) {
		case 'record':
			$url = maars_legacy_record_url( (string) $ref );
			break;
		case 'file':
			$url = maars_legacy_file_url( (string) $ref );
			break;
		case 'page':
			$url = home_url( (string) $ref );
			break;
		case 'gaps':
			$url = home_url( '/archive/gaps/' );
			break;
		case 'gone':
			return array( 410, '', false );
		case 'away':
			return 0 === strpos( (string) $ref, 'http' ) ? array( 301, (string) $ref, true ) : array( 0, '', false );
		default:
			$url = '';
	}

	return '' !== $url ? array( 301, $url, false ) : array( 0, '', false );
}

/**
 * Redirect an old address that would otherwise be a 404.
 *
 * @return void
 */
function maars_legacy_redirect(): void {
	if ( ! is_404() || empty( $_SERVER['REQUEST_URI'] ) ) {
		return;
	}

	$path = (string) wp_parse_url( wp_unslash( $_SERVER['REQUEST_URI'] ), PHP_URL_PATH ); // phpcs:ignore WordPress.Security.ValidatedSanitizedInput.InputNotSanitized
	$home = (string) wp_parse_url( home_url( '/' ), PHP_URL_PATH );
	if ( '' !== $home && '/' !== $home && 0 === strpos( $path, $home ) ) {
		$path = '/' . substr( $path, strlen( $home ) );
	}
	$name = rawurldecode( trim( $path, '/' ) );
	if ( '' === $name ) {
		return;
	}

	list( $status, $url, $away ) = maars_legacy_target( $name );
	if ( 410 === $status ) {
		status_header( 410 );
		return;                           /* the 404 template, with the right status */
	}
	if ( 301 !== $status ) {
		return;
	}
	/* An address from the generated map, never from the request, so the
	   off-site redirect cannot be steered by a visitor. */
	$sent = $away ? wp_redirect( $url, 301, 'MAARS legacy address' ) : wp_safe_redirect( $url, 301, 'MAARS legacy address' ); // phpcs:ignore WordPress.Security.SafeRedirect.wp_redirect_wp_redirect
	if ( $sent ) {
		exit;
	}
}
add_action( 'template_redirect', 'maars_legacy_redirect', 1 );
